cannibalism_try_pay_humane_route_screening_cost = {
	set_temp_variable = { cannibalism_humane_screening_result = 0 }
	cannibalism_find_expected_spread_row_for_screening = yes
	if = {
		limit = {
			check_variable = { cannibalism_spread_queue_validation_result > 0 }
			check_variable = { cannibalism_expected_spread_row_found > 0 }
			cannibalism_can_pay_humane_route_screening_cost = yes
			event_target:cannibalism_screening_state = { cannibalism_screening_state_matches_expected_spread = yes }
		}
		set_temp_variable = { cannibalism_spread_cost_manpower = constant:cannibalism_spread.humane_screening_manpower }
		multiply_temp_variable = { cannibalism_spread_cost_manpower = -1 }
		add_manpower = cannibalism_spread_cost_manpower
		set_temp_variable = { cannibalism_spread_cost_support = constant:cannibalism_spread.humane_screening_support }
		multiply_temp_variable = { cannibalism_spread_cost_support = -1 }
		add_equipment_to_stockpile = { type = support_equipment_1 amount = cannibalism_spread_cost_support producer = ROOT }
		set_temp_variable = { cannibalism_spread_cost_command = constant:cannibalism_spread.humane_screening_command }
		multiply_temp_variable = { cannibalism_spread_cost_command = -1 }
		add_command_power = cannibalism_spread_cost_command
		add_stability = constant:cannibalism_spread.humane_screening_stability
		event_target:cannibalism_screening_state = {
			set_state_flag = cannibalism_spread_screening_active
			set_state_flag = cannibalism_spread_screening_humane
			clr_state_flag = cannibalism_spread_screening_hard
		}
		set_temp_variable = { cannibalism_humane_screening_result = 1 }
	}
}

cannibalism_try_pay_hard_route_screening_cost = {
	set_temp_variable = { cannibalism_hard_screening_result = 0 }
	cannibalism_find_expected_spread_row_for_screening = yes
	if = {
		limit = {
			check_variable = { cannibalism_spread_queue_validation_result > 0 }
			check_variable = { cannibalism_expected_spread_row_found > 0 }
			cannibalism_can_pay_hard_route_screening_cost = yes
			event_target:cannibalism_screening_state = { cannibalism_screening_state_matches_expected_spread = yes }
		}
		set_temp_variable = { cannibalism_spread_cost_manpower = constant:cannibalism_spread.hard_screening_manpower }
		multiply_temp_variable = { cannibalism_spread_cost_manpower = -1 }
		add_manpower = cannibalism_spread_cost_manpower
		set_temp_variable = { cannibalism_spread_cost_support = constant:cannibalism_spread.hard_screening_support }
		multiply_temp_variable = { cannibalism_spread_cost_support = -1 }
		add_equipment_to_stockpile = { type = support_equipment_1 amount = cannibalism_spread_cost_support producer = ROOT }
		set_temp_variable = { cannibalism_spread_cost_command = constant:cannibalism_spread.hard_screening_command }
		multiply_temp_variable = { cannibalism_spread_cost_command = -1 }
		add_command_power = cannibalism_spread_cost_command
		add_stability = constant:cannibalism_spread.hard_screening_stability
		add_war_support = constant:cannibalism_spread.hard_screening_war_support
		event_target:cannibalism_screening_state = {
			set_state_flag = cannibalism_spread_screening_active
			set_state_flag = cannibalism_spread_screening_hard
			clr_state_flag = cannibalism_spread_screening_humane
		}
		if = {
			limit = { is_cannibalism_active_ordinary_country = yes }
			add_to_variable = { cannibalism_command_integrity = constant:cannibalism_spread.hard_screening_integrity }
			cannibalism_clamp_current_country_meters = yes
			cannibalism_refresh_country_penalty_variables = yes
		}
		set_temp_variable = { cannibalism_hard_screening_result = 1 }
	}

cannibalism_record_integrated_warlord_slot = {
