	else_if = { limit = { check_variable = { cannibalism_integration_slot_index = constant:cannibalism_slot.cbg } } set_country_flag = cannibalism_integrated_warlord_cbg set_variable = { cannibalism_integrated_warlord_cbg_disposition = cannibalism_integration_disposition } }
	else_if = { limit = { check_variable = { cannibalism_integration_slot_index = constant:cannibalism_slot.cbh } } set_country_flag = cannibalism_integrated_warlord_cbh set_variable = { cannibalism_integrated_warlord_cbh_disposition = cannibalism_integration_disposition } }
}

